 "content": "def transform(grid):
    # Shift the entire grid down one cell; fill the top row with its background color.
    if not grid:
        return []
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    return [[bg] * len(grid[0])] + [row[:] for row in grid[:-1]]
